from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        # Follow jump chains until reaching a cell that starts no jump.
        while x in jump:
            x = jump[x]
        return x

    # States are non-jump cells in [0, n-1]; n is the absorbing end cell.
    def successors(x: int) -> list[int]:
        res = []
        for r in range(1, m + 1):
            y = x + r
            if y > n:
                y = 2 * n - y  # bounce back from the end
            res.append(resolve(y))
        return res

    states = [x for x in range(n) if x not in jump]
    succ = {x: successors(x) for x in states}

    # Reachable states from the start cell 0.
    reachable = set()
    stack = [0]
    while stack:
        x = stack.pop()
        if x == n or x in reachable:
            continue
        reachable.add(x)
        stack.extend(succ[x])

    # States that can reach the end with positive probability.
    good = {n}
    changed = True
    while changed:
        changed = False
        for x in states:
            if x not in good and any(y in good for y in succ[x]):
                good.add(x)
                changed = True

    # If some reachable state can never finish, the game may never end.
    if any(x not in good for x in reachable):
        return None

    # Build E[x] = 1 + (1/m) * sum E[y] over reachable states as a linear system.
    order = sorted(reachable)
    idx = {x: i for i, x in enumerate(order)}
    k = len(order)
    inv_m = Fraction(1, m)

    mat = []
    for x in order:
        row = [Fraction(0)] * (k + 1)
        row[idx[x]] += 1
        for y in succ[x]:
            if y != n:
                row[idx[y]] -= inv_m
        row[k] = Fraction(1)
        mat.append(row)

    # Gauss-Jordan elimination with exact fractions.
    for col in range(k):
        pivot = next(r for r in range(col, k) if mat[r][col] != 0)
        mat[col], mat[pivot] = mat[pivot], mat[col]
        pv = mat[col][col]
        mat[col] = [v / pv for v in mat[col]]
        for r in range(k):
            if r != col and mat[r][col] != 0:
                f = mat[r][col]
                mat[r] = [a - f * b for a, b in zip(mat[r], mat[col])]

    ans = mat[idx[0]][k]
    return [ans.numerator, ans.denominator]
